package com.bicheon.advisor.dev356;
import android.app.*;import android.os.*;import android.content.*;import android.media.projection.*;import android.net.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{static final int O=1,C=2;TextView s;public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(40,60,40,40);TextView t=new TextView(this);t.setText("비천 매치 추천기 v3.5.6 RECOVERY");t.setTextSize(24);l.addView(t);s=new TextView(this);s.setText("준비 완료");s.setTextSize(17);l.addView(s);Button a=new Button(this);a.setText("분석 시작");l.addView(a);a.setOnClickListener(v->startAuth());Button z=new Button(this);z.setText("분석 중지");l.addView(z);z.setOnClickListener(v->{stopService(new Intent(this,AdvisorService.class));s.setText("중지됨");});setContentView(l);}void startAuth(){try{if(!Settings.canDrawOverlays(this)){startActivityForResult(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())),O);s.setText("다른 앱 위 표시 권한을 허용하세요");return;}MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),C);s.setText("화면 공유 권한을 허용하세요");}catch(Throwable e){s.setText("권한 요청 오류: "+e.getClass().getSimpleName());}}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==O){if(Settings.canDrawOverlays(this))startAuth();return;}if(r==C&&c==RESULT_OK&&d!=null){try{Intent i=new Intent(this,AdvisorService.class);i.putExtra("rc",c);i.putExtra("data",d);startForegroundService(i);s.setText("분석 시작 완료");}catch(Throwable e){s.setText("서비스 시작 오류: "+e.getClass().getSimpleName());}}}}
